class TaskForm(forms.ModelForm):
    class Meta:
        model = Task
        fields = ['name', 'description', 'owner', 'external_owner', 'start_date', 'end_date', 'status', 'dependencies']
        widgets = {
            'start_date': DateInput(),
            'end_date': DateInput(),
            'dependencies': forms.CheckboxSelectMultiple,
        }

    def __init__(self, *args, **kwargs):
        project = kwargs.pop('project', None)
        super(TaskForm, self).__init__(*args, **kwargs)

        if not project and self.instance and self.instance.pk:
            project = self.instance.project

        if project:
            tasks = Task.objects.filter(project=project)
            if self.instance and self.instance.pk:
                tasks = tasks.exclude(pk=self.instance.pk)
            self.fields['dependencies'].queryset = tasks

        self.fields['dependencies'].required = False

